package com.smarttvmanager.guard

import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

/**
 * Signature check for commands sent with `adb shell am broadcast`.
 *
 * The receiver has to be exported (the adb shell is another UID), so any app on the TV could try
 * to send commands. A shared secret, generated by the desktop app, keeps them out. The signed
 * message binds the command name, a strictly increasing sequence number (epoch milliseconds,
 * which blocks replays) and the payload.
 */
object CommandAuth {
    const val MAX_FUTURE_SKEW_MS = 5 * 60 * 1000L

    fun message(cmd: String, seq: Long, payload: String): ByteArray =
        "$cmd\n$seq\n$payload".toByteArray(Charsets.UTF_8)

    fun sign(secret: ByteArray, cmd: String, seq: Long, payload: String): String {
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(secret, "HmacSHA256"))
        return mac.doFinal(message(cmd, seq, payload)).joinToString("") { "%02x".format(it) }
    }

    fun verify(
        secret: ByteArray,
        cmd: String,
        seq: Long,
        payload: String,
        sig: String,
        lastSeq: Long,
        nowMs: Long,
    ): Boolean {
        if (seq <= lastSeq) return false
        if (seq > nowMs + MAX_FUTURE_SKEW_MS) return false
        val expected = sign(secret, cmd, seq, payload).toByteArray(Charsets.UTF_8)
        return MessageDigest.isEqual(expected, sig.lowercase().toByteArray(Charsets.UTF_8))
    }
}
